import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    if n == 1:
        return 'C' if opp_last == 'C' else 'D'

    opp_moves = [o for _, o in history]
    my_moves = [m for m, _ in history]

    opp_c = 0
    my_c = 0
    for i in range(n):
        if opp_moves[i] == 'C':
            opp_c += 1
        if my_moves[i] == 'C':
            my_c += 1
    opp_def = n - opp_c
    opp_coop_rate = opp_c / n

    k = min(10, n)
    recent_opp_def = 0
    for i in range(n - k, n):
        if opp_moves[i] == 'D':
            recent_opp_def += 1

    k2 = min(5, n)
    recent5_opp_def = 0
    for i in range(n - k2, n):
        if opp_moves[i] == 'D':
            recent5_opp_def += 1

    streak = 1
    for i in range(n - 1, 0, -1):
        if opp_moves[i] == opp_moves[i - 1]:
            streak += 1
        else:
            break

    # Endgame exploitation: if opponent has been mostly cooperative, defect hard.
    if n >= 92:
        if opp_coop_rate >= 0.6:
            return 'D'
        if opp_last == 'D':
            return 'D'
        if recent_opp_def >= 3:
            return 'D'
        return 'C'

    # Very cooperative opponent: keep cooperating, probe rarely.
    if opp_coop_rate >= 0.9 and opp_last == 'C':
        if n < 85 and n % 13 == 0 and rng.random() < 0.15:
            return 'D'
        return 'C'

    # Extremely exploitative opponent: defect.
    if opp_coop_rate <= 0.2 and n >= 8:
        return 'D'

    # Long defection streak: mostly defect, rarely test.
    if opp_last == 'D' and streak >= 5:
        if n < 90 and rng.random() < 0.1:
            return 'C'
        return 'D'

    # Frequent recent defection.
    if recent_opp_def >= 7:
        return 'D'

    # Moderate recent defection: retaliate.
    if recent_opp_def >= 4:
        if opp_last == 'C' and recent5_opp_def <= 1:
            if rng.random() < 0.3:
                return 'D'
            return 'C'
        return 'D'

    # Long cooperation streak: cooperate, occasional mild probe.
    if opp_last == 'C' and streak >= 6:
        if n < 88 and n % 17 == 0 and rng.random() < 0.2:
            return 'D'
        return 'C'

    # Tit-for-tat core with forgiveness and slight exploitation.
    if opp_last == 'C':
        if my_last == 'D' and rng.random() < 0.15:
            return 'D'
        if n > 30 and opp_coop_rate > 0.8 and n % 19 == 0 and rng.random() < 0.25:
            return 'D'
        return 'C'
    else:
        # Opponent defected.
        if recent_opp_def <= 2 and opp_coop_rate > 0.55:
            if rng.random() < 0.35:
                return 'C'
        if rng.random() < 0.1 and n < 90:
            return 'C'
        return 'D'
